<?php use app\services\Ui;use yii\helpers\Html;$this->title='HEMIS integratsiyasi'; ?>
<?php if(Yii::$app->user->identity->role==='superadmin' && !empty($archivedHemisCount)): ?><div class="alert warning">Bazadagi <?= (int)$archivedHemisCount ?> ta HEMIS hisobi o‘chirilgan holatda. Ularni qaytarish uchun pastdagi “O‘chirilgan HEMIS hisoblarini qayta tiklash” belgisini tanlab, xodimlarni import qiling.</div><?php endif ?><div class="page-heading"><div><span class="eyebrow">TASHQI MA’LUMOTLAR</span><h1>HEMIS integratsiyasi</h1><p>Tashkilot tuzilmasi va xodimlarni rasmiy API orqali yuklang.</p></div></div><div class="form-grid"><section class="card"><h2>Ulanish sozlamalari</h2><?= Html::beginForm(['admin/hemis'],'post') ?><?= Html::hiddenInput('operation','configure') ?><?= Ui::input('HEMIS domeni','host',$settings['host']??'','text',['required'=>true,'placeholder'=>'hemis.universitet.uz']) ?><?= Ui::input('API kaliti (saqlanganni qoldirish uchun bo‘sh qoldiring)','token','','password',['autocomplete'=>'new-password']) ?><p class="muted"><?= empty($settings['token'])?'API kaliti hali saqlanmagan.':'API kaliti saqlangan. Xavfsizlik uchun maydon bosh korsatiladi. Bosh qoldirsangiz oldingi kalit saqlanadi.' ?></p><button class="button">Sozlamalarni saqlash</button><?= Html::endForm() ?></section><aside class="card form-note"><h2>Import tartibi</h2><p>Avval tuzilmani, keyin xodimlarni yuklang. Mavjud yozuvlar HEMIS identifikatori bilan yangilanadi.</p><p>Yangi xodimlar nofaol va rol biriktirilmagan holatda yaratiladi. Rolni faqat superadministrator belgilaydi. Administrator ularning toifasi, vaqtinchalik paroli va faolligini tekshirib ochadi.</p><p>HEMIS administratori API kaliti bilan bergan backend domenidan foydalaning. Student kabineti domeni REST API domenidan farq qilishi mumkin.</p><p>Domen server tarmoq ruxsatlarida ochiq bo‘lishi kerak. Kalitni chatga yubormang.</p></aside></div><section class="card"><h2>Ma’lumotlarni yuklash</h2><div class="actions"><?php foreach(['test'=>'Ulanishni tekshirish','structure'=>'Tuzilmani import qilish','employees'=>'Xodimlarni import qilish'] as $op=>$label): if($op!=='test' && Yii::$app->user->identity->role!=='superadmin')continue; ?><?= Html::beginForm(['admin/hemis'],'post') ?><?= Html::hiddenInput('operation',$op) ?><?php if($op==='employees'): ?><div id="employee-import"><label class="check"><?= Html::checkbox('restore_deleted',false,['value'=>'1']) ?> O‘chirilgan HEMIS hisoblarini qayta tiklash</label><p class="muted">Tiklangan hisoblar ro‘yxatga nofaol holatda qaytadi. Eski ID, parol, rol va hujjatlar saqlanadi.</p></div><?php endif ?><?php if($op==='structure'): ?><?= Ui::select('Universitet','university_id','',array_column($universities,'name','id'),['required'=>true]) ?><?php endif ?><button class="button secondary"><?= Ui::h($label) ?></button><?= Html::endForm() ?><?php endforeach ?></div><p class="muted">Import mavjud hisoblarning paroli, roli, KPI toifasi va faolligini o‘zgartirmaydi. Pasport va JSHIR ma’lumotlari olinmaydi.</p></section>

<?php if(!empty($lastImport)): ?><section class="card"><h2>Oxirgi xodimlar importi</h2><p class="muted"><?= Ui::h($lastImport['finished_at']??'') ?></p><dl class="details"><?php foreach(['received'=>'HEMISdan olingan','created'=>'Yangi hisob','updated'=>'Yangilangan','restored'=>'Qayta tiklangan','unique_users'=>'Ro‘yxatga yozilgan xodimlar','skipped'=>'O‘tkazilgan','unlinked'=>'Bo‘limga bog‘lanmagan'] as $key=>$label): if($key==='unique_users' && !array_key_exists($key,$lastImport))continue; ?><div><dt><?= Ui::h($label) ?></dt><dd><?= (int)($lastImport[$key]??0) ?></dd></div><?php endforeach ?></dl><?php foreach($lastImport['reasons']??[] as $reason=>$count): ?><p><?= Ui::h($reason) ?>: <?= (int)$count ?></p><?php endforeach ?><p class="muted">Import qilingan nofaol hisoblar “Foydalanuvchilar” ro‘yxatida ko‘rinadi. Kirish uchun vaqtinchalik parol, toifa va faollik belgilang; rolni superadministrator biriktiradi.</p></section><?php endif ?>
